changeSet.sql:
ALTER TABLE feedback DROP CONSTRAINT IF EXISTS chk_feedback_state;
ALTER TABLE feedback ADD CONSTRAINT chk_feedback_state
    CHECK (delivery_state IN (
        'AWAITING_APPROVAL', 'PREPARED', 'PARTIALLY_DELIVERED', 'PARTIALLY_FAILED', 'DELIVERED',
        'DISCARDED', 'SUPERSEDED', 'SUPPRESSED', 'FAILED', 'UNCONFIRMED'));

changeSet.rollback:
UPDATE feedback SET delivery_state = 'DELIVERED' WHERE delivery_state = 'UNCONFIRMED';
